let t_sintonia = 'ND';
try {
  const sintoniaResp = $json;
  const dadosSintonia = sintoniaResp?.dados || [];
  if (Array.isArray(dadosSintonia) && dadosSintonia.length > 0) {
    const hoje = new Date();
    const anoMesAtual = hoje.getFullYear() * 100 + (hoje.getMonth() + 1);
    if (Number(dadosSintonia[0].mesValidadeSelo) >= anoMesAtual) {
      t_sintonia = 'A+';
    }
  }
} catch (e) {
  // Qualquer erro aqui (formato inesperado, chamada anterior falhou) -> ND, nunca trava o D1.
  t_sintonia = 'ND';
}

return [{ json: { t_sintonia } }];

// Pega o pgfn_fallback_payload de qualquer um dos dois branches que rodou
// (só um dos dois sempre roda, nunca os dois — usa try/catch porque referenciar
// um node que não executou nesta run lança erro).
let pgfnFallbackPayload = null;
try {
  pgfnFallbackPayload = $('Com Fallback PGFN').first().json.pgfn_fallback_payload;
} catch (e) {
  try {
    pgfnFallbackPayload = $('Sem Fallback PGFN').first().json.pgfn_fallback_payload;
  } catch (e2) {
    pgfnFallbackPayload = null;
  }
}
return [{ json: { pgfn_fallback_payload: pgfnFallbackPayload } }];

const cnd = $('Infosimples · CND Federal').first().json.data?.[0] ?? null;
const est = $('Direct Data · CND Estadual').first().json.retorno ?? null;
const pgfnFallback = $('Consolidar PGFN Fallback').first().json.pgfn_fallback_payload;
const pgfnLista = pgfnFallback ? pgfnFallback.retorno ?? null : null;
const t_sintonia = $('Classificar Sintonia').first().json.t_sintonia ?? 'ND';

let t_cnd = "Não obtida";
let t_pgfn = "Não verificado";

if (cnd) {
  const tipo = cnd.tipo || "";
  if (tipo.includes("efeitos de negativa")) t_cnd = "Positiva c/ efeitos de negativa";
  else if (tipo === "Positiva") t_cnd = "Positiva";
  else if (tipo === "Negativa") t_cnd = "Negativa";

  t_pgfn = "Não";
  if (cnd.debitos_pgfn === true) {
    t_pgfn = tipo.includes("efeitos de negativa") ? "Parcelada/garantida" : "Irregular";
  }
} else if (pgfnLista) {
  // Fallback: Infosimples não emitiu a certidão (ex: code 611), mas a Direct Data
  // confirma via cadastro público de devedores. t_cnd continua "Não obtida"
  // (nenhuma fonte alternativa emite a certidão em si), só t_pgfn é recuperado.
  t_pgfn = pgfnLista.possuiDivida === false ? "Não" : "Irregular";
}

let t_est = "ND";
if (est) {
  t_est = (!est.possuiDebito || est.efeitoNegativa) ? "Regular" : "Irregular";
}

const gateDisparado = (t_cnd === "Positiva" && t_pgfn === "Irregular")
  ? "G3: CND federal positiva + PGFN irregular"
  : null;

return [{ json: { t_cnd, t_pgfn, t_est, t_sintonia, gate_disparado: gateDisparado } }];
